'use strict';
(()=>{
const nav=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Рассылки');nav.disabled=false;
const page=document.createElement('main');page.hidden=true;page.id='campaigns-page';
page.innerHTML=`<div class="breadcrumb">Коммуникации / Рассылки</div><div class="heading"><div><h1>Рассылки</h1><p>Аудитории, письмо и расписание</p></div><button class="outline" id="cmp-new">Новая рассылка</button></div>
<div class="demo"><b>Подготовка рассылок</b><span>Сохраняйте планы и проверяйте состав получателей. Очередь работает в имитации — письма не отправляются.</span></div>
<section class="panel"><div class="section-title"><h2>Черновики и очереди</h2><button class="outline" id="cmp-refresh">Обновить</button></div><div id="cmp-list" class="table-scroll"></div></section>
<section class="panel" id="cmp-editor" hidden><h2 id="cmp-title">Новая рассылка</h2><label>Название рассылки<input id="cmp-name" maxlength="160" placeholder="Например, ноябрьские предложения"></label>
<nav id="cmp-steps" aria-label="Шаги мастера"></nav>
<section data-cmp-step="0"><h3>1. Получатели</h3><p>Выберите одну или несколько аудиторий. Подкатегории включаются автоматически; один email учитывается один раз.</p><div id="cmp-audiences" class="cmp-audiences"></div><div id="cmp-counts" role="status"></div></section>
<section data-cmp-step="1" hidden><h3>2. Шаблон письма</h3><label>Сохранённый шаблон<select id="cmp-template" aria-label="Сохранённый шаблон"><option value="">Выберите шаблон</option></select></label><p id="cmp-template-note"></p><p>Сначала сохраните письмо в разделе «Шаблоны». В черновике рассылки сохраняется копия выбранной версии.</p><iframe id="cmp-preview" title="Письмо для рассылки" sandbox="" referrerpolicy="no-referrer"></iframe></section>
<section data-cmp-step="2" hidden><h3>3. Отправитель</h3><label>Отправитель<select id="cmp-sender" aria-label="Отправитель"><option value="">Выберите отправителя</option></select></label><p id="cmp-sender-note"></p><details><summary>Добавить отправителя</summary><form id="cmp-sender-form"><label>Имя отправителя<input name="name" maxlength="160" required placeholder="OVER"></label><label>Email отправителя<input name="email" type="email" maxlength="254" required placeholder="news@example.kz"></label><label>Email для ответов (необязательно)<input name="reply_to" type="email" maxlength="254"></label><button class="outline" type="submit">Добавить</button><p role="status" id="cmp-sender-status"></p></form></details><p>Это реквизиты письма. Подтверждение домена и настройка SMTP будут выполнены при подключении отправки.</p></section>
<section data-cmp-step="3" hidden><h3>4. Расписание</h3><label>Способ запуска<select id="cmp-mode" aria-label="Способ запуска"><option value="manual">После ручного запуска</option><option value="scheduled">В указанное время</option></select></label><label>Часовой пояс<select id="cmp-zone" aria-label="Часовой пояс"><option>Asia/Qyzylorda</option><option>Asia/Almaty</option><option>UTC</option></select></label><label id="cmp-date-label" hidden>Дата и время<input id="cmp-date" type="datetime-local"></label><p>Расписание сохраняется в черновике. Автоматическая отправка станет доступна после подключения очереди и транспорта.</p></section>
<section data-cmp-step="4" hidden><h3>5. Проверка плана</h3><button class="outline" id="cmp-recount">Пересчитать и проверить</button><div id="cmp-review" aria-live="polite"></div></section>
<div class="cmp-actions"><button class="outline" id="cmp-back">Назад</button><button class="primary" id="cmp-next">Далее</button><button class="primary" id="cmp-save" hidden>Сохранить черновик</button></div><p role="status" id="cmp-status"></p></section>`;
document.body.append(page);
const style=document.createElement('style');style.textContent=`#campaigns-page label{display:block;margin:12px 0}#campaigns-page label>input:not([type=checkbox]),#campaigns-page label>select{display:block;width:100%;max-width:640px;box-sizing:border-box}#campaigns-page input:focus,#campaigns-page select:focus{outline:none;border-color:#6BAEE0;box-shadow:0 0 0 2px #0795e918}#campaigns-page button{width:auto;flex:none;min-height:36px}#cmp-steps,.cmp-actions{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}#cmp-steps [aria-current=step]{background:#edf7fc;border-color:#0088cc;color:#0088cc}#cmp-audiences{max-height:340px;overflow:auto;border:1px solid #dde5ec;border-radius:6px;padding:12px}#cmp-audiences label{display:flex;align-items:center;gap:8px;margin:8px 0}#cmp-audiences input{width:auto}#cmp-preview{width:100%;max-width:800px;height:450px;border:1px solid #dde5ec;background:white;box-sizing:border-box}.cmp-count-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:16px 0}.cmp-count-grid div{padding:12px;border:1px solid #dde5ec;border-radius:6px}.cmp-count-grid strong{display:block;font-size:22px;margin-top:6px}.cmp-warnings{padding:12px;background:#fff8e8;border-radius:6px}#cmp-review dt{font-weight:600}#cmp-review dd{margin:4px 0 14px}#cmp-list td,#cmp-list th{padding:12px;text-align:left}@media(max-width:700px){#cmp-steps button{flex:1 1 42%}.cmp-actions button{flex:1 1 auto}#cmp-audiences{max-height:260px}}`;document.head.append(style);
const $=key=>document.getElementById('cmp-'+key),store='campaign-wizard-state';
let campaignLocked=false;
let step=0,current=null,templates=[],senders=[],templateRevision=null,busy=false,countToken=0,previewToken=0;
const titles=['Получатели','Шаблон','Отправитель','Расписание','Проверка'];
function text(tag,value){const el=document.createElement(tag);el.textContent=value;return el;}
function status(message){$('status').textContent=message;}
function state(){return {queue:campaignLocked?{mode:'simulation'}:null,id:current?.id,revision:current?.revision,name:$('name').value,audience_ids:[...$('audiences').querySelectorAll('input:checked')].map(e=>Number(e.value)),template_id:Number($('template').value)||null,template_revision:templateRevision,sender_id:Number($('sender').value)||null,schedule_mode:$('mode').value,schedule_timezone:$('zone').value,scheduled_at:$('date').value};}
function remember(){if($('editor').hidden)return;try{sessionStorage.setItem(store,JSON.stringify({data:state(),step}));}catch{}}
function stepError(index){const data=state();if(index===0&&!data.audience_ids.length)return 'Выберите хотя бы одну аудиторию.';if(index===1&&!data.template_id)return 'Выберите сохранённый шаблон.';if(index===2&&!data.sender_id)return 'Выберите отправителя.';if(index===3&&data.schedule_mode==='scheduled'&&!data.scheduled_at)return 'Укажите дату и время.';return '';}
function showStep(index){step=index;page.querySelectorAll('[data-cmp-step]').forEach(e=>e.hidden=Number(e.dataset.cmpStep)!==step);[...$('steps').children].forEach((b,i)=>{b.setAttribute('aria-current',i===step?'step':'false');b.disabled=busy;});$('back').disabled=step===0||busy;$('next').hidden=step===4;$('save').hidden=step!==4;$('save').disabled=busy||campaignLocked;$('next').disabled=busy;remember();if(step===4)review();}
for(let i=0;i<titles.length;i++){const b=text('button',`${i+1}. ${titles[i]}`);b.className='outline';b.onclick=()=>{for(let j=0;j<i;j++){const error=stepError(j);if(error){status(error);return;}}status('');showStep(i);};$('steps').append(b);}
function countsBox(counts,host){host.replaceChildren();const grid=document.createElement('div');grid.className='cmp-count-grid';for(const [key,label]of [['contacts','Контактов в аудиториях'],['unique_emails','Уникальных email'],['without_email','Контактов без email'],['duplicates','Повторных email в контактах'],['archived','В архиве'],['suppressed','Запрет отправки'],['invalid','Ошибка email'],['pending','Ожидают проверки'],['ready','После исключений']]){const box=text('div',label);box.append(text('strong',String(counts[key])));grid.append(box);}host.append(grid,text('small','Категории исключений не пересекаются. Состав пересчитывается; перед отправкой потребуется актуальная проверка.'));}
async function count(){const token=++countToken;if(!state().audience_ids.length){$('counts').textContent='Выберите аудиторию для расчёта.';return;}try{const c=await api('/api/campaigns/recipients',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({audience_ids:state().audience_ids})});if(token===countToken)countsBox(c,$('counts'));}catch(e){if(token===countToken)$('counts').textContent=e.message;}}
function senderNote(){const s=senders.find(s=>s.id===Number($('sender').value));$('sender-note').textContent=s?`${s.name} <${s.email}> · Ответы: ${s.reply_to||s.email}`:'';}
function safePreview(html){const doc=new DOMParser().parseFromString(html,'text/html');for(const link of doc.querySelectorAll('a,area')){link.removeAttribute('href');link.removeAttribute('target');}for(const el of doc.querySelectorAll('base,meta[http-equiv],script,iframe,object,embed'))el.remove();return doc.documentElement.outerHTML;}
async function templatePreview(){const token=++previewToken;const id=Number($('template').value);if(!id){$('preview').srcdoc='';$('template-note').textContent='';return;}try{const t=await api('/api/templates/'+id);if(token!==previewToken)return;$('template-note').textContent=`Тема: ${t.subject||'Не указана'} · Версия ${t.revision}`+(t.revision!==templateRevision?' · Шаблон изменился: выберите его заново перед сохранением.':'');$('preview').srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; form-action 'none'; base-uri 'none'">`+safePreview(t.html);}catch(e){if(token===previewToken)$('template-note').textContent=e.message;}}
async function options(){const [a,t,s]=await Promise.all([api('/api/audiences'),api('/api/templates'),api('/api/campaign-senders')]);templates=t.templates;senders=s.senders;$('audiences').replaceChildren();const byId=new Map(a.audiences.map(row=>[row.id,row]));function path(row,seen=new Set()){if(!row||seen.has(row.id))return '';seen.add(row.id);return row.parent_id?path(byId.get(row.parent_id),seen)+' → '+row.name:row.name;}for(const row of a.audiences.sort((x,y)=>path(x).localeCompare(path(y),'ru'))){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=row.id;label.append(input,document.createTextNode(path(row)));$('audiences').append(label);}$('template').replaceChildren(new Option('Выберите шаблон',''));for(const t of templates)$('template').add(new Option(t.name,String(t.id)));senderOptions();}
function senderOptions(){const value=$('sender').value;$('sender').replaceChildren(new Option('Выберите отправителя',''));for(const s of senders)$('sender').add(new Option(`${s.name} <${s.email}>`,String(s.id)));$('sender').value=value;}
function localDate(value,zone){if(!value)return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value)).replace(' ','T');}
async function fill(data={},saved=false){page.inert=true;try{await options();current=data.id?{id:data.id,revision:data.revision}:null;campaignLocked=!!data.queue;$('title').textContent=current?'Черновик рассылки':'Новая рассылка';$('editor').hidden=false;$('name').value=data.name||'';for(const input of $('audiences').querySelectorAll('input'))input.checked=(data.audience_ids||[]).includes(Number(input.value));$('template').value=String(data.template_id||'');templateRevision=data.template_revision||data.template_snapshot?.revision||templates.find(t=>t.id===data.template_id)?.revision||null;$('sender').value=String(data.sender_id||'');$('mode').value=data.schedule_mode||'manual';$('zone').value=data.schedule_timezone||'Asia/Qyzylorda';$('date').value=saved?localDate(data.scheduled_at,$('zone').value):(data.scheduled_at||'');$('date-label').hidden=$('mode').value!=='scheduled';$('review').replaceChildren();senderNote();await templatePreview();await count();}finally{page.inert=false;}}
async function review(){const token=++previewToken;$('review').textContent='Пересчёт и проверка…';$('save').disabled=true;try{const result=await api('/api/campaigns/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state())});if(token!==previewToken)return;const host=$('review');host.replaceChildren();const details=document.createElement('dl');const time=result.scheduled_at?`${new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium',timeStyle:'short',timeZone:result.schedule_timezone}).format(new Date(result.scheduled_at))} (${result.schedule_timezone})`:'После ручного запуска';for(const [label,value]of [['Рассылка',result.name],['Аудитории',[...$('audiences').querySelectorAll('label')].filter(e=>e.querySelector('input').checked).map(e=>e.textContent).join(', ')],['Шаблон',`${result.template.name} · версия ${result.template.revision}`],['Тема',result.template.subject],['Отправитель',`${result.sender.name} <${result.sender.email}>`],['Ответы',result.sender.reply_to||result.sender.email],['Расписание',time]])details.append(text('dt',label),text('dd',value));host.append(details);const counts=document.createElement('div');countsBox(result.counts,counts);host.append(counts);const warnings=document.createElement('div');warnings.className='cmp-warnings';for(const warning of result.warnings)warnings.append(text('p',warning));for(const finding of result.checks.findings||[])warnings.append(text('p',finding.message));host.append(warnings);$('save').disabled=busy||campaignLocked;}catch(e){if(token===previewToken){$('review').textContent=e.message;status(e.message);}}}
async function list(){try{const result=await api('/api/campaigns');$('list').replaceChildren();if(!result.campaigns.length){$('list').textContent='Пока нет рассылок. Создайте первый черновик.';return;}const table=document.createElement('table'),head=document.createElement('tr');head.className='cmp-list-heading';for(const label of ['Название','Состояние','Получателей при сохранении','Расписание',''])head.append(text('th',label));table.append(head);for(const row of result.campaigns){const tr=document.createElement('tr');tr.className='cmp-list-row';for(const value of [row.name,row.queue?'Очередь: '+({paused:'пауза',running:'обработка',completed:'завершена',cancelled:'отменена'}[row.queue.state]||row.queue.state)+' (имитация)':'Черновик · '+(row.approval?.label||'Не согласована'),String(row.recipient_counts.ready??0),row.scheduled_at?`${new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short',timeZone:row.schedule_timezone}).format(new Date(row.scheduled_at))} (${row.schedule_timezone})`:'Ручной запуск'])tr.append(text('td',value));const cell=document.createElement('td'),open=text('button','Открыть');open.className='outline';open.onclick=async()=>{try{await fill(await api('/api/campaigns/'+row.id),true);status(campaignLocked?'Для этой рассылки уже создана очередь; состав и письмо зафиксированы. Создайте новую рассылку для изменений.':'Черновик загружен. Состав получателей пересчитан.');showStep(0);}catch(e){status(e.message);}};const queueButton=text('button','Очередь (имитация)');queueButton.className='outline';queueButton.onclick=()=>window.CampaignQueue.open(row.id).then(list);const statsButton=text('button','Демо-статистика');statsButton.className='outline';statsButton.onclick=()=>window.CampaignStatistics.open(row.id);const readinessButton=text('button','Проверка готовности');readinessButton.className='outline';readinessButton.onclick=()=>window.CampaignReadiness.open(row.id);const checkButton=text('button','Проверить письмо');checkButton.className='outline';checkButton.onclick=()=>window.CampaignMailCheck.open(row.id,'preview');const ownStats=text('button','Статистика');ownStats.className='outline';ownStats.onclick=()=>window.CampaignMailCheck.open(row.id,'stats');const auditButton=text('button','Журнал действий');auditButton.className='outline';auditButton.onclick=()=>window.ActionJournal.open(row.id);cell.className='cmp-list-actions';const approvalButton=text('button','Согласование');approvalButton.className='outline';approvalButton.onclick=()=>window.CampaignApproval.open(row.id);cell.append(approvalButton,auditButton,open,checkButton,readinessButton,queueButton,ownStats,statsButton);tr.append(cell);[...tr.children].forEach((td,index)=>td.dataset.label=['Название','Состояние','Получателей при сохранении','Расписание','Действия'][index]);table.append(tr);}$('list').append(table);if(result.total>200)$('list').append(text('p','Показаны последние 200 черновиков.'));}catch(e){$('list').textContent=e.message;}}
$('next').onclick=()=>{const error=stepError(step);if(error){status(error);return;}status('');showStep(step+1);};$('back').onclick=()=>{status('');showStep(Math.max(0,step-1));};$('recount').onclick=review;
$('audiences').onchange=()=>{remember();count();};$('template').onchange=()=>{templateRevision=templates.find(t=>t.id===Number($('template').value))?.revision||null;remember();templatePreview();};$('sender').onchange=()=>{senderNote();remember();};$('mode').onchange=()=>{$('date-label').hidden=$('mode').value!=='scheduled';remember();};page.addEventListener('input',remember);page.addEventListener('change',remember);
$('sender-form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));const row=await api('/api/campaign-senders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});senders.push(row);senderOptions();$('sender').value=String(row.id);senderNote();remember();form.reset();$('sender-status').textContent='Отправитель добавлен.';}catch(e){$('sender-status').textContent=e.message;}finally{button.disabled=false;}};
$('save').onclick=async()=>{if(busy||campaignLocked)return;busy=true;page.inert=true;$('save').disabled=true;try{const row=await api('/api/campaigns'+(current?'/'+current.id:''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state())});current={id:row.id,revision:row.revision};$('title').textContent='Черновик рассылки';remember();status(`Черновик сохранён. Получателей после исключений: ${row.recipient_counts.ready}. Отправка не запускалась.`);await list();}catch(e){status(e.message);}finally{busy=false;page.inert=false;$('save').disabled=false;}};
$('new').onclick=async()=>{try{await fill();status('');showStep(0);}catch(e){status(e.message);}};$('refresh').onclick=list;document.addEventListener('campaign-approval-changed',list);
document.querySelector('aside nav').addEventListener('click',event=>{const target=event.target.closest('button');if(!target||target.disabled)return;if(target===nav){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});nav.classList.add('active');nav.setAttribute('aria-current','page');document.title='Рассылки';try{sessionStorage.setItem('campaigns-open','1');}catch{}list();}else{remember();page.hidden=true;try{sessionStorage.removeItem('campaigns-open');}catch{}}});
window.addEventListener('pagehide',remember);
(async()=>{try{if(sessionStorage.getItem('campaigns-open')!=='1')return;nav.click();const saved=JSON.parse(sessionStorage.getItem(store)||'null');if(saved?.data){await fill(saved.data);status('Восстановлены поля мастера. Сохраните черновик в БД.');showStep(Math.min(4,Math.max(0,saved.step||0)));}}catch(e){status(e.message);}})();
})();
